files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 3px solid var(--accent);
  border-radius: 0;
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  text-align: center;
  box-shadow: 6px 6px 0 #0f0f1a;
}

h1 {
  margin: 0 0 16px;
  font-size: 28px;
  letter-spacing: 2px;
  color: var(--accent);
  text-transform: uppercase;
}

.question {
  font-size: 24px;
  margin: 0 0 24px;
  min-height: 36px;
}

.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 20px;
  padding: 12px 24px;
  border: 3px solid var(--accent);
  background: var(--bg);
  color: var(--text);
  cursor: pointer;
  border-radius: 0;
  transition: background 0.1s, transform 0.05s;
  min-width: 80px;
}

.btn:hover:not(:disabled) {
  background: var(--accent);
  color: var(--bg);
}

.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.btn:active:not(:disabled) {
  transform: translate(2px, 2px);
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.score-label {
  font-size: 20px;
  margin: 0 0 24px;
  color: var(--muted);
}

#score {
  color: var(--accent);
  font-weight: bold;
}

.actions {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.action {
  font-size: 18px;
  padding: 10px 20px;
}

@media (max-width: 360px) {
  .card {
    padding: 24px 16px;
  }
  .btn {
    font-size: 18px;
    padding: 10px 16px;
  }
}

(function () {
  'use strict';

  var state = {
    q: 1,
    score: 0,
    locked: false
  };

  var questionEl = document.getElementById('question');
  var answerA = document.getElementById('answer-a');
  var answerB = document.getElementById('answer-b');
  var scoreEl = document.getElementById('score');
  var nextBtn = document.getElementById('next');
  var restartBtn = document.getElementById('restart');

  var questions = {
    1: { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
    2: { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
  };

  function render() {
    if (state.q === 1 || state.q === 2) {
      var q = questions[state.q];
      questionEl.textContent = q.text;
      answerA.textContent = q.a;
      answerB.textContent = q.b;
      answerA.disabled = false;
      answerB.disabled = false;
      state.locked = false;
    } else {
      questionEl.textContent = 'Finished';
      answerA.disabled = true;
      answerB.disabled = true;
    }
    scoreEl.textContent = String(state.score);
  }

  function handleAnswer(choice) {
    if (state.locked || state.q > 2) return;
    state.locked = true;
    answerA.disabled = true;
    answerB.disabled = true;
    var q = questions[state.q];
    if (choice === q.correct) {
      state.score += 1;
      scoreEl.textContent = String(state.score);
    }
  }

  answerA.addEventListener('click', function () { handleAnswer('a'); });
  answerB.addEventListener('click', function () { handleAnswer('b'); });

  nextBtn.addEventListener('click', function () {
    if (state.q === 1 && state.locked) {
      state.q = 2;
      render();
    } else if (state.q === 2 && state.locked) {
      state.q = 3;
      render();
    } else if (state.q === 3) {
      render();
    }
  });

  restartBtn.addEventListener('click', function () {
    state.q = 1;
    state.score = 0;
    state.locked = false;
    render();
  });

  render();
})();
